import { getAvailableTeams } from "../helpers/teamHelpers";
import React, { useState, useEffect, useMemo } from "react";
import {
  Button,
  Select,
  MenuItem,
  InputLabel,
  Checkbox,
  FormControlLabel,
} from "@material-ui/core";

function TournamentSetup({
  teams: fallbackTeams,
  teamData,
  onStartTournament,
  onBack,
}) {
  const [selectedTeams, setSelectedTeams] = useState([]);
  const [selectedOvers, setSelectedOvers] = useState(50);
  const [structure, setStructure] = useState("round_robin");

  const oversOptions = [
    { value: 20, label: "T20 (20 Overs)", format: "T20" },
    { value: 40, label: "ODI (40 Overs)", format: "ODI_40" },
    { value: 50, label: "ODI (50 Overs)", format: "ODI_50" },
  ];

  const selectedFormat =
    oversOptions.find((opt) => opt.value === selectedOvers)?.format || "ODI_50";
  const teams = useMemo(
    () =>
      teamData ? getAvailableTeams(teamData, selectedFormat) : fallbackTeams,
    [teamData, selectedFormat, fallbackTeams]
  );
  const allTeamsSelected = selectedTeams.length === teams.length;
  useEffect(() => {
    setSelectedTeams((selected) => {
      const valid = selected.filter((team) => teams.includes(team));
      return valid.length === selected.length ? selected : valid;
    });
  }, [teams]);
  const handleTeamToggle = (team) => {
    if (selectedTeams.includes(team)) {
      setSelectedTeams(selectedTeams.filter((t) => t !== team));
    } else {
      setSelectedTeams([...selectedTeams, team]);
    }
  };

  const handleSelectAllTeams = () => {
    setSelectedTeams(allTeamsSelected ? [] : [...teams]);
  };

  const handleStart = () => {
    if (selectedTeams.length < 3) {
      alert("Please select at least 3 teams for the tournament");
      return;
    }
    const selectedFormat =
      oversOptions.find((opt) => opt.value === selectedOvers)?.format ||
      "ODI_50";
    onStartTournament({
      teams: selectedTeams,
      overs: selectedOvers,
      format: selectedFormat,
      structure:
        selectedTeams.length === 3 || structure !== "group_stage"
          ? "round_robin"
          : "group_stage",
    });
  };

  return (
    <div style={{ marginLeft: "35%", marginTop: "2%", maxWidth: "400px" }}>
      <h2 style={{ color: "whitesmoke" }}>Tournament Setup</h2>

      <div style={{ marginBottom: 20 }}>
        <InputLabel style={{ color: "whitesmoke", marginBottom: 10 }}>
          Select Teams (min 3)
        </InputLabel>
        <p style={{ color: "#bbb", margin: "0 0 8px 0" }}>
          Selected: {selectedTeams.length}/{teams.length}
        </p>
        <FormControlLabel
          control={
            <Checkbox
              checked={allTeamsSelected}
              onChange={handleSelectAllTeams}
              style={{ color: "whitesmoke" }}
            />
          }
          label={
            <span style={{ color: "whitesmoke" }}>
              {allTeamsSelected ? "Unselect All Teams" : "Select All Teams"}
            </span>
          }
          style={{ display: "block", marginBottom: 8 }}
        />
        {teams.map((team) => (
          <FormControlLabel
            key={team}
            control={
              <Checkbox
                checked={selectedTeams.includes(team)}
                onChange={() => handleTeamToggle(team)}
                style={{ color: "whitesmoke" }}
              />
            }
            label={<span style={{ color: "whitesmoke" }}>{team}</span>}
            style={{ display: "block" }}
          />
        ))}
      </div>

      <InputLabel shrink style={{ color: "whitesmoke" }}>
        Overs
      </InputLabel>
      <Select
        value={selectedOvers}
        onChange={(e) => setSelectedOvers(e.target.value)}
        style={{ color: "whitesmoke", marginBottom: 20, width: "100%" }}
      >
        {oversOptions.map((option) => (
          <MenuItem value={option.value} key={option.value}>
            {option.label}
          </MenuItem>
        ))}
      </Select>
      <br />
      <br />

      <InputLabel shrink style={{ color: "whitesmoke" }}>
        Tournament Structure
      </InputLabel>
      <Select
        value={selectedTeams.length === 3 ? "round_robin" : structure}
        onChange={(e) => setStructure(e.target.value)}
        inputProps={{ "aria-label": "Tournament Structure" }}
        style={{ color: "whitesmoke", marginBottom: 10, width: "100%" }}
      >
        <MenuItem value="round_robin">Round Robin</MenuItem>
        <MenuItem value="group_stage" disabled={selectedTeams.length < 4}>
          Two-Group Stage
        </MenuItem>
      </Select>
      <p style={{ color: "#bbb", marginTop: 0 }}>
        {selectedTeams.length === 3
          ? "Tri-series: every team plays the other two teams twice, followed by a final between the top two."
          : structure === "group_stage"
          ? "Teams are split into two groups before the knockout stage."
          : "Every team plays every other team once before the knockout stage."}
      </p>
      <br />

      <Button
        variant="contained"
        color="primary"
        onClick={handleStart}
        style={{ marginRight: 10 }}
      >
        Start Tournament
      </Button>
      <Button
        variant="outlined"
        style={{ color: "whitesmoke" }}
        onClick={onBack}
      >
        Back
      </Button>
    </div>
  );
}

export default TournamentSetup;
